create extension if not exists pgcrypto;

create table if not exists public.firma_solicitudes (id uuid primary key default gen_random_uuid(),documento_id uuid,contrato_id uuid,operacion_id uuid not null references public.operaciones(id) on delete cascade,empresa_solicitante_id uuid,firmante_email text not null,firmante_nombre text not null,firmante_rol text not null,token_hash text not null unique,documento_hash text not null,documento_tipo text not null,documento_nombre text not null,documento_contenido text not null,estado text not null default 'PENDIENTE' check (estado in ('PENDIENTE','FIRMADO','RECHAZADO','EXPIRADO','CANCELADO')),expira_at timestamptz not null default (now()+interval '72 hours'),firmado_at timestamptz,creado_por uuid not null references public.profiles(id),creado_at timestamptz not null default now(),actualizado_at timestamptz not null default now());
create table if not exists public.firmas_electronicas (id uuid primary key default gen_random_uuid(),solicitud_id uuid not null unique references public.firma_solicitudes(id) on delete cascade,firmante_nombre text not null,firmante_email text not null,consentimiento boolean not null,declaracion text not null,firma_nombre text not null,documento_hash text not null,evidencia_hash text not null,ip_address inet,user_agent text,metadata jsonb not null default '{}'::jsonb,firmado_at timestamptz not null default now());
create table if not exists public.firma_eventos (id uuid primary key default gen_random_uuid(),solicitud_id uuid not null references public.firma_solicitudes(id) on delete cascade,evento text not null,actor_profile_id uuid references public.profiles(id),ip_address inet,user_agent text,metadata jsonb not null default '{}'::jsonb,creado_at timestamptz not null default now());
create index if not exists idx_firma_solicitudes_operacion on public.firma_solicitudes(operacion_id); create index if not exists idx_firma_solicitudes_estado on public.firma_solicitudes(estado); create index if not exists idx_firma_eventos_solicitud on public.firma_eventos(solicitud_id);
alter table public.firma_solicitudes enable row level security; alter table public.firmas_electronicas enable row level security; alter table public.firma_eventos enable row level security; revoke all on public.firma_solicitudes,public.firmas_electronicas,public.firma_eventos from anon,authenticated;
create or replace function public.crear_solicitud_firma_contrato(p_contrato_id uuid,p_firmante_email text,p_firmante_nombre text,p_firmante_rol text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_contrato public.contratos%rowtype; v_token text; v_hash text; v_id uuid; v_hash_doc text; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; select * into v_contrato from public.contratos where id=p_contrato_id for update; if not found then raise exception 'CONTRACT_NOT_FOUND'; end if; if not public.usuario_participa_operacion(v_contrato.operacion_id) then raise exception 'FORBIDDEN'; end if; if v_contrato.estado<>'CONFIRMADO' then raise exception 'CONTRACT_MUST_BE_CONFIRMED'; end if; if nullif(trim(p_firmante_email),'') is null or nullif(trim(p_firmante_nombre),'') is null then raise exception 'SIGNER_DATA_REQUIRED'; end if; v_token:=encode(gen_random_bytes(32),'hex'); v_hash:=encode(digest(v_token,'sha256'),'hex'); v_hash_doc:=encode(digest(convert_to(coalesce(v_contrato.contenido,''),'utf8'),'sha256'),'hex'); insert into public.firma_solicitudes(contrato_id,operacion_id,empresa_solicitante_id,firmante_email,firmante_nombre,firmante_rol,token_hash,documento_hash,documento_tipo,documento_nombre,documento_contenido,creado_por) select p_contrato_id,v_contrato.operacion_id,p.active_company_id,trim(lower(p_firmante_email)),trim(p_firmante_nombre),trim(p_firmante_rol),v_hash,v_hash_doc,'CONTRATO',coalesce(v_contrato.numero_contrato,'Contrato')||'.txt',coalesce(v_contrato.contenido,''),v_uid from public.profiles p where p.id=v_uid returning id into v_id; insert into public.firma_eventos(solicitud_id,actor_profile_id,evento,metadata) values(v_id,v_uid,'SOLICITADA',jsonb_build_object('firmante_rol',p_firmante_rol)); return jsonb_build_object('id',v_id,'token',v_token,'expira_at',now()+interval '72 hours'); end; $$;
create or replace function public.obtener_solicitud_firma(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_s public.firma_solicitudes%rowtype; begin select * into v_s from public.firma_solicitudes where token_hash=encode(digest(p_token,'sha256'),'hex') for update; if not found then raise exception 'SIGN_REQUEST_NOT_FOUND'; end if; if v_s.estado='PENDIENTE' and v_s.expira_at<now() then update public.firma_solicitudes set estado='EXPIRADO',actualizado_at=now() where id=v_s.id; raise exception 'SIGN_REQUEST_EXPIRED'; end if; if v_s.estado<>'PENDIENTE' then raise exception 'SIGN_REQUEST_NOT_ACTIVE'; end if; return jsonb_build_object('id',v_s.id,'operacion_id',v_s.operacion_id,'documento_tipo',v_s.documento_tipo,'documento_nombre',v_s.documento_nombre,'documento_contenido',v_s.documento_contenido,'documento_hash',v_s.documento_hash,'firmante_email',v_s.firmante_email,'firmante_nombre',v_s.firmante_nombre,'firmante_rol',v_s.firmante_rol,'expira_at',v_s.expira_at); end; $$;
create or replace function public.registrar_firma_electronica(p_token text,p_nombre text,p_consentimiento boolean,p_declaracion text,p_ip inet default null,p_user_agent text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_s public.firma_solicitudes%rowtype; v_evidence text; v_id uuid; begin select * into v_s from public.firma_solicitudes where token_hash=encode(digest(p_token,'sha256'),'hex') for update; if not found then raise exception 'SIGN_REQUEST_NOT_FOUND'; end if; if v_s.estado<>'PENDIENTE' then raise exception 'SIGN_REQUEST_NOT_ACTIVE'; end if; if v_s.expira_at<now() then update public.firma_solicitudes set estado='EXPIRADO',actualizado_at=now() where id=v_s.id; raise exception 'SIGN_REQUEST_EXPIRED'; end if; if not p_consentimiento then raise exception 'CONSENT_REQUIRED'; end if; if lower(trim(coalesce(p_nombre,'')))<>lower(trim(v_s.firmante_nombre)) then raise exception 'SIGNER_NAME_MISMATCH'; end if; if length(trim(coalesce(p_declaracion,'')))<20 then raise exception 'DECLARATION_REQUIRED'; end if; v_evidence:=encode(digest(convert_to(v_s.documento_hash||'|'||trim(p_nombre)||'|'||trim(p_declaracion)||'|'||coalesce(p_user_agent,'')||'|'||coalesce(p_ip::text,''),'utf8'),'sha256'),'hex'); insert into public.firmas_electronicas(solicitud_id,firmante_nombre,firmante_email,consentimiento,declaracion,firma_nombre,documento_hash,evidencia_hash,ip_address,user_agent) values(v_s.id,v_s.firmante_nombre,v_s.firmante_email,true,trim(p_declaracion),trim(p_nombre),v_s.documento_hash,v_evidence,p_ip,p_user_agent) returning id into v_id; update public.firma_solicitudes set estado='FIRMADO',firmado_at=now(),actualizado_at=now() where id=v_s.id; insert into public.firma_eventos(solicitud_id,evento,ip_address,user_agent,metadata) values(v_s.id,'FIRMADO',p_ip,p_user_agent,jsonb_build_object('evidencia_hash',v_evidence,'firma_id',v_id)); return jsonb_build_object('ok',true,'firma_id',v_id,'evidencia_hash',v_evidence,'firmado_at',now()); end; $$;
revoke all on function public.crear_solicitud_firma_contrato(uuid,text,text,text) from public,anon; grant execute on function public.crear_solicitud_firma_contrato(uuid,text,text,text) to authenticated;
revoke all on function public.obtener_solicitud_firma(text) from public,anon,authenticated; grant execute on function public.obtener_solicitud_firma(text) to service_role;
revoke all on function public.registrar_firma_electronica(text,text,boolean,text,inet,text) from public,anon,authenticated; grant execute on function public.registrar_firma_electronica(text,text,boolean,text,inet,text) to service_role;